fn warning(s: *Scope, chalk: c.JSValue, diagnostic: c.JSValue) !void {
    // Outer callee/reference first, then the live chalk method, then the
    // template's message Get and ToString. Neither result is normalized.
    const console = try v.global(s, "console");
    const warn = try v.get(s, console, "warn");
    const yellow = try v.get(s, chalk, "yellow");
    const message = try v.stringify(s, try v.get(s, diagnostic, "message"));
    const text = try h.binary(s, .add, try v.text(s, "Warning: "), message);
    const colored = try v.call(s, yellow, chalk, &.{text});
    _ = try v.call(s, warn, console, &.{colored});
}

